import type { ReactNode } from 'react';

import { AdminDataTable, AdminTablePaginationFooter, AdminTableScroll } from '../../components/admin-data-table';
import { AdminStageItem, AdminStageList } from '../../components/admin-stage-item';
import { AdminDisclosure } from '../../components/admin-surface';
import { AdminTablePanel } from '../../components/admin-table-panel';
import { AdminTextLink } from '../../components/admin-text-link';
import { MoneyText } from '../../components/money-text';
import { StatusBadgeFromPillClass } from '../../components/status-badge';
import { adminCountLabel } from '../../lib/admin-copy';

export type RefundActionExecutionRow = {
  readonly action: string;
  readonly operatorRule: string;
  readonly pillClass: string;
  readonly reason: string;
  readonly status: string;
};

export type RefundTableRow = {
  readonly ageLabel: string;
  readonly amount: number;
  readonly assigneeLabel: string;
  readonly bookingHref: string;
  readonly bookingIdLabel: string;
  readonly bookingStatus: string;
  readonly currency: string;
  readonly customerLabel: string;
  readonly createdAtLabel: string;
  readonly executionRows: readonly RefundActionExecutionRow[];
  readonly id: string;
  readonly opsHint: string;
  readonly opsSignal: ReactNode;
  readonly paymentHref: string;
  readonly paymentLabel: string;
  readonly reason: string;
  readonly shortId: string;
  readonly stageLabel: string;
};

type RefundsTableSectionProps = {
  readonly emptyMessage: string;
  readonly pagination: {
    readonly from: number;
    readonly hrefForPage: (page: number) => string;
    readonly page: number;
    readonly rows: readonly RefundTableRow[];
    readonly to: number;
    readonly totalPages: number;
    readonly totalRows: number;
  };
};

export function RefundsTableSection({ emptyMessage, pagination }: RefundsTableSectionProps) {
  const rows = pagination.rows;

  return (
    <AdminTablePanel
      description="Refund cases ordered for decision, payment follow-up, and state reconciliation."
      resultLabel={adminCountLabel(pagination.totalRows, 'refund')}
      resultTone={pagination.totalRows > 0 ? 'info' : 'warning'}
      title="Refund operations"
    >
      <AdminTableScroll>
        <AdminDataTable
          className="vuexy-booking-table"
          emptyMessage={emptyMessage}
          headers={['Age', 'Customer', 'Amount', 'Reason', 'Evidence', 'Payment', 'Owner', 'Next action']}
          rowCount={rows.length}
        >
          {rows.map((row) => (
            <tr id={`refund-${row.id}`} key={row.id}>
              <td>
                <strong>{row.ageLabel}</strong>
                <div className="muted">{row.createdAtLabel}</div>
                <div className="muted">Refund {row.shortId}</div>
              </td>
              <td>{row.customerLabel}</td>
              <td>
                <MoneyText amount={row.amount} currency={row.currency} />
              </td>
              <td>{row.reason}</td>
              <td>
                <strong>{row.stageLabel}</strong>
                <div className="muted">Booking {row.bookingIdLabel} / {row.bookingStatus}</div>
                <AdminTextLink href={row.bookingHref}>Open booking</AdminTextLink>
              </td>
              <td>
                <strong>{row.paymentLabel}</strong>
                <div><AdminTextLink href={row.paymentHref}>Open payment</AdminTextLink></div>
              </td>
              <td>{row.assigneeLabel}</td>
              <td>
                <div>{row.opsSignal}</div>
                <div className="muted admin-mt-8">{row.opsHint}</div>
                <AdminDisclosure className="admin-mt-10">
                  <summary>Decision evidence</summary>
                  <AdminStageList className="admin-mt-8">
                    {row.executionRows.map((item) => (
                      <AdminStageItem key={`${row.id}-${item.action}`}>
                        <StatusBadgeFromPillClass pillClass={item.pillClass}>
                          {item.status}
                        </StatusBadgeFromPillClass>
                        <div>
                          <strong>{item.action}</strong>
                          <p className="muted">{item.reason}</p>
                          <small>{item.operatorRule}</small>
                        </div>
                      </AdminStageItem>
                    ))}
                  </AdminStageList>
                </AdminDisclosure>
              </td>
            </tr>
          ))}
        </AdminDataTable>
      </AdminTableScroll>
      <AdminTablePaginationFooter
        activePage={pagination.page}
        ariaLabel="Refund pagination"
        from={pagination.from}
        hrefForPage={pagination.hrefForPage}
        to={pagination.to}
        totalPages={pagination.totalPages}
        totalRows={pagination.totalRows}
      />
    </AdminTablePanel>
  );
}
