import { AdminSegmentedControl } from '../../components/admin-segmented-control';
import { AdminFilterSummary } from '../../components/admin-filter-summary';
import { AdminTablePanel } from '../../components/admin-table-panel';
import { AdminDisclosure } from '../../components/admin-surface';
import type { AdminDateRange } from '../../lib/date-range';
import type {
  AdminQueueAge,
  AdminQueueAgeCounts,
  AdminQueueSlaSummary,
  AdminQueueSlaFilter,
  AdminQueueSort,
} from '../../lib/admin-queue-list';
import { adminQueueSlaFilterLabel } from '../../lib/admin-queue-list';
import { AdminQueueAgeSortControls } from '../../components/admin-queue-age-sort-controls';

export type RefundFilterLink = {
  readonly href: string;
  readonly label: string;
  readonly review: string;
};

export type RefundRangeLink = {
  readonly href: string;
  readonly label: string;
  readonly range: AdminDateRange;
};

type RefundFilterBoardSectionProps = {
  readonly age?: AdminQueueAge;
  readonly ageCounts?: AdminQueueAgeCounts;
  readonly ageHref?: (age: AdminQueueAge) => string;
  readonly queueSla?: AdminQueueSlaSummary;
  readonly sla?: AdminQueueSlaFilter;
  readonly slaHref?: (sla: AdminQueueSlaFilter) => string;
  readonly activeFilterDescription: string | null;
  readonly activeFilterLabel: string | null;
  readonly activeRange: AdminDateRange;
  readonly customerProfileId: string;
  readonly filteredCount: number;
  readonly rangeLabel: string;
  readonly rangeLinks: readonly RefundRangeLink[];
  readonly review: string;
  readonly reviewLinks: readonly RefundFilterLink[];
  readonly totalCount: number;
  readonly sort?: AdminQueueSort;
  readonly sortHref?: (sort: AdminQueueSort) => string;
};

export function RefundFilterBoardSection({
  age = 'all',
  ageCounts,
  ageHref = (value) => `?age=${value}`,
  queueSla,
  sla = 'all',
  slaHref,
  activeFilterDescription,
  activeFilterLabel,
  activeRange,
  customerProfileId,
  filteredCount,
  rangeLabel,
  rangeLinks,
  review,
  reviewLinks,
  totalCount,
  sort = 'newest',
  sortHref = (value) => `?sort=${value}`,
}: RefundFilterBoardSectionProps) {
  const isFiltered = Boolean(review || activeRange !== 'all' || customerProfileId);
  const showAdvancedFilters =
    activeRange !== 'today' || Boolean(customerProfileId) || age !== 'all' || sla !== 'all' || sort !== 'newest';

  return (
    <AdminTablePanel
      description={
        <>
          Current queue: <strong>{activeFilterLabel ?? 'All refunds'}</strong>
          {activeFilterDescription ? ` - ${activeFilterDescription}` : '.'}
        </>
      }
      resultLabel={`Showing ${filteredCount} of ${totalCount}`}
      resultTone={review ? 'warning' : 'success'}
      title="Refund operation filters"
    >
      <div className="booking-date-filter-bar refund-filter-group">
        <span className="refund-filter-group-label">Queue</span>
        <AdminSegmentedControl
          activeValue={review || 'all'}
          ariaLabel="Refund review filters"
          className="refund-filter-buttons"
          options={[
            ...(isFiltered
              ? [{ href: '/refunds?range=all&review=all', label: 'Clear filters', value: 'clear' }]
              : []),
            ...reviewLinks.map((item) => ({
              href: item.href,
              label: item.label,
              value: item.review,
            })),
          ]}
        />
      </div>
      <AdminDisclosure
        ariaLabel="Advanced refund filters"
        className="admin-mt-12"
        open={showAdvancedFilters}
      >
        <summary>
          <span>Advanced filters</span>
          <small>Range, age, SLA, and sort</small>
        </summary>
        <div className="admin-disclosure-content">
          <AdminFilterSummary
            ariaLabel="Active refund filters"
            className="admin-mb-12"
            labels={[
              `Range: ${rangeLabel}`,
              ...(customerProfileId ? [`Customer: ${customerProfileId}`] : []),
              `Age: ${age === 'all' ? 'All ages' : age}`,
              ...(sla !== 'all' ? [`SLA: ${adminQueueSlaFilterLabel(sla)}`] : []),
              `Order: ${sort === 'oldest' ? 'Oldest first' : 'Newest first'}`,
            ]}
            tone="info"
          />
          <AdminQueueAgeSortControls
            age={age}
            ageCounts={ageCounts}
            ageHref={ageHref}
            sla={queueSla}
            slaFilter={sla}
            slaHref={slaHref}
            sort={sort}
            sortHref={sortHref}
          />
          <div className="booking-date-filter-bar refund-filter-group admin-mt-12">
            <span className="refund-filter-group-label">Range</span>
            <AdminSegmentedControl
              activeValue={activeRange}
              ariaLabel="Refund date range filters"
              className="refund-filter-buttons"
              options={rangeLinks.map((item) => ({
                href: item.href,
                label: item.label,
                value: item.range,
              }))}
            />
          </div>
        </div>
      </AdminDisclosure>
    </AdminTablePanel>
  );
}
